"""Hypothesis testing."""
from nodespec import N

N("null_hypothesis", "definition", "testing",
  "The null hypothesis H0: theta in Theta_0 is the statement about theta put on trial; it is retained unless the data provide strong evidence against it. Theta_0 subset Theta.",
  parseable="H0: theta in Theta_0    (Theta_0 a specified subset of Theta)",
  symbols={"Theta_0": "the null parameter set (a point for a 'simple' null, a set for a 'composite' null)",
           "'on trial'": "the asymmetry -- Type I error (wrongly rejecting H0) is controlled, Type II is not"},
  tcn="A subset of Theta, chosen before seeing the data. The test controls the probability of rejecting H0 when it is true; it does NOT control the probability of accepting a false H0. 'Fail to reject' is not 'accept'.",
  spec=["simple: H0: mu = 0 (Theta_0 a single point)",
        "composite one-sided: H0: mu <= 0",
        "composite with nuisance: H0: mu = 0, sigma^2 > 0 arbitrary"],
  cxd={"specified_in_advance": "choosing Theta_0 after seeing the data (testing the hypothesis the data suggest) invalidates the Type I error control -- 'the garden of forking paths'"},
  misuse=["interpreting 'fail to reject H0' as 'H0 is true' -- it may just be low power",
          "testing a point null (mu exactly 0) that is known a priori to be false, then declaring 'significance' at large n as if it were news"],
  related={"required_by": ["alternative_hypothesis", "test_function", "size_of_test", "neyman_pearson_lemma"]},
  sources=["lehmann_romano_tsh", "casella_berger_2e"])

N("alternative_hypothesis", "definition", "testing",
  "The alternative hypothesis H1: theta in Theta_1 is the set of parameter values the test is designed to detect; usually Theta_1 = Theta \\ Theta_0.",
  parseable="H1: theta in Theta_1    (typically Theta \\ Theta_0)",
  symbols={"Theta_1": "the alternative set -- one-sided (mu > 0) or two-sided (mu != 0)",
           "the direction of H1": "determines whether a one- or two-tailed test is used"},
  tcn="A subset of Theta disjoint from (the closure of) Theta_0. The alternative is where POWER is measured; the choice of one- vs two-sided must be made before seeing the data.",
  spec=["two-sided: H1: mu != 0 -- detect an effect in either direction",
        "one-sided: H1: mu > 0 -- more powerful against positive effects, blind to negative ones",
        "restricted: H1: theta in a cone (order-restricted alternatives)"],
  cxd={"chosen_in_advance": "switching from two-sided to one-sided after seeing a positive Xbar doubles the effective alpha"},
  misuse=["choosing a one-sided alternative post hoc to cross the 0.05 threshold",
          "a one-sided test that would not reject even for an enormous effect in the unanticipated direction"],
  related={"uses": ["null_hypothesis"], "required_by": ["power_function"]},
  sources=["lehmann_romano_tsh"])

N("test_function", "definition", "testing",
  "A test is a function phi: X^n -> [0, 1] giving the probability of rejecting H0 when the data are x; a nonrandomized test takes values in {0, 1} with rejection region { x : phi(x) = 1 }.",
  parseable="phi: X^n -> [0, 1];   reject H0 with probability phi(x)",
  symbols={"phi(x) = 1": "reject", "phi(x) = 0": "do not reject", "phi(x) in (0,1)": "reject with that probability (randomized -- needed for exact size on discrete data)"},
  tcn="A [0,1]-valued statistic. Randomization matters only for discrete data where no nonrandomized region has exactly the target size; in practice one reports the p-value instead.",
  spec=["phi(x) = 1{ T(x) > c } -- reject for large values of a test statistic T",
        "two-sided: phi(x) = 1{ |T(x)| > c }",
        "randomized: phi(x) = gamma when T(x) = c, to hit an exact size on a lattice"],
  cxd={"measurable": "a non-measurable rejection region has no size -- excluded"},
  misuse=["treating a randomized test's coin flip as scientifically meaningful (report the p-value)",
          "choosing the rejection region's shape to reject the observed data"],
  related={"specializes_from": ["statistic"], "required_by": ["size_of_test", "power_function", "neyman_pearson_lemma"],
           "dual_of": ["confidence_set"]},
  sources=["lehmann_romano_tsh", "casella_berger_2e"])

N("size_of_test", "definition", "testing",
  "The size of a test phi is alpha(phi) = sup_{theta in Theta_0} E_theta[phi(X)], the largest Type I error probability over the null; phi has level alpha if its size is <= alpha.",
  parseable="size(phi) = sup_{theta in Theta_0} E_theta[ phi(X) ];   phi is level-alpha if size(phi) <= alpha",
  symbols={"E_theta[phi(X)] = P_theta(reject H0)": "the rejection probability at theta",
           "sup over Theta_0": "the worst-case Type I rate -- what 'level alpha' bounds"},
  tcn="A supremum over the null set. 'Size' is the exact worst-case Type I rate; 'level' is any upper bound one is willing to claim. For a simple null Theta_0 = {theta_0} the sup is just E_{theta_0}[phi].",
  regime="exact",
  spec=["one-sample t-test, H0: mu = mu_0: size exactly alpha (the t-statistic is pivotal under the whole null since it does not depend on sigma^2)",
        "a composite null H0: mu <= 0: the size is attained at the boundary mu = 0",
        "discrete data (binomial test): the achievable sizes form a lattice; a nonrandomized test is conservative (size < nominal alpha)"],
  cxd={"sup_attained_or_controlled": "if the null contains a nuisance parameter over which the rejection probability is not maximized at a computable point (Behrens-Fisher), the exact size is unknown and one uses an approximately-similar test"},
  misuse=["quoting 'level 0.05' when the actual size under a composite null exceeds 0.05 at some nuisance value",
          "confusing size (a pre-data property of the procedure) with the p-value (a post-data statistic)"],
  related={"uses": ["test_function", "null_hypothesis"], "required_by": ["neyman_pearson_lemma", "p_value", "confidence_set_test_duality", "type_i_error"]},
  sources=["lehmann_romano_tsh", "casella_berger_2e"])

N("power_function", "definition", "testing",
  "The power function of a test phi is beta_phi(theta) = E_theta[phi(X)] for all theta in Theta; on Theta_1 it is the power (probability of correctly rejecting), on Theta_0 it is the Type I error rate.",
  parseable="beta_phi(theta) = E_theta[ phi(X) ],   theta in Theta",
  symbols={"beta_phi(theta)": "one function giving both the Type I profile (on Theta_0) and the power (on Theta_1)",
           "power at a specific alternative theta_1": "beta_phi(theta_1) = 1 - P(Type II error at theta_1)"},
  tcn="A single function on all of Theta. An ideal test has beta_phi <= alpha on Theta_0 and beta_phi close to 1 on Theta_1. Power increases with n, with the effect size, and with alpha; it decreases with variance.",
  regime="exact",
  spec=["one-sample z-test power at mu_1: Phi( sqrt(n)(mu_1 - mu_0)/sigma - z_{1-alpha} ) for a one-sided test",
        "sample-size formula: solve beta_phi(mu_1) = 1 - beta for n given a target alternative mu_1 and power 1 - beta",
        "the power of the LRT against local alternatives theta_0 + h/sqrt(n) tends to a noncentral chi^2 tail probability"],
  cxd={"none_all_hypotheses_essential": "the power function is defined for any test; the content is its shape"},
  misuse=["reporting 'observed power' computed at the estimated effect after a non-significant result -- it is a deterministic function of the p-value and adds nothing (Hoenig-Heisey 2001)",
          "designing a study with 50% power and treating a null result as informative"],
  apps=["prospective power / sample-size calculation is a regulatory requirement for clinical trials (ICH E9)",
        "the basis of 'minimum detectable effect' reporting in A/B testing platforms"],
  related={"uses": ["test_function", "alternative_hypothesis"], "special_case_of": ["risk_function"],
           "required_by": ["neyman_pearson_lemma", "karlin_rubin_theorem"]},
  sources=["lehmann_romano_tsh", "cohen_power_analysis"])

N("type_i_error", "definition", "testing",
  "A Type I error is rejecting H0 when it is true (probability <= the size alpha); a Type II error is failing to reject H0 when it is false (probability 1 - power at that alternative).",
  parseable="Type I: reject | H0 true  (rate <= alpha);   Type II: accept | H1 true  (rate = 1 - beta_phi(theta_1))",
  symbols={"alpha": "the tolerated Type I rate", "1 - beta_phi(theta_1)": "the Type II rate at alternative theta_1"},
  tcn="The two error kinds, treated asymmetrically: alpha is fixed by convention (0.05, 0.01, 5 sigma), power is then maximized. Which error is 'Type I' depends on which hypothesis is labelled the null -- a modelling choice reflecting which mistake is worse.",
  spec=["drug trial: Type I = approve an ineffective drug (H0: no effect); Type II = miss an effective one",
        "the trade-off at fixed n: lowering alpha raises the Type II rate; only increasing n lowers both",
        "5-sigma in particle physics: alpha ~ 3e-7, an extremely low Type I tolerance"],
  cxd={"H0_is_the_costlier_false_positive": "if the roles are mislabelled, the procedure rigidly protects the wrong error -- e.g. an equivalence trial must put 'the treatments differ' style framing correctly (H0: not equivalent)"},
  misuse=["treating a non-significant result as proof of H0 (ignoring the uncontrolled Type II rate)",
          "running many tests and reporting the significant ones without multiplicity adjustment -- the family-wise Type I rate balloons"],
  related={"uses": ["size_of_test", "power_function"]},
  sources=["lehmann_romano_tsh", "neyman_pearson_1933"])

N("neyman_pearson_lemma", "theorem", "testing",
  "For testing a simple null H0: X ~ f0 against a simple alternative H1: X ~ f1, the likelihood-ratio test phi*(x) = 1{ f1(x) > k f0(x) } (with randomization on the boundary to reach exact size alpha) is the most powerful level-alpha test; and any most powerful level-alpha test has this form a.e.",
  parseable="H0: f0  vs  H1: f1.   phi*(x) = 1{ f1(x) > k f0(x) },  E_{f0}[phi*] = alpha   =>   phi* maximizes E_{f1}[phi]  among all level-alpha phi",
  symbols={"f1/f0": "the likelihood ratio -- the optimal test statistic",
           "k": "the critical value chosen so the size is exactly alpha",
           "phi*": "the (possibly randomized) NP test"},
  tcn="An optimality theorem, exact and finite-sample. Proof (sufficiency): for any other level-alpha test phi, the function (phi* - phi)(f1 - k f0) is >= 0 pointwise (check the two cases f1 > k f0 and f1 < k f0); integrate: E_{f1}[phi*] - E_{f1}[phi] >= k ( E_{f0}[phi*] - E_{f0}[phi] ) >= 0.",
  regime="exact",
  hyps=[],
  proof=("the pointwise inequality (phi*(x) - phi(x))(f1(x) - k f0(x)) >= 0 for every x, then integrate against the dominating measure",
         "size_of_test", "core",
         "validation/proof-checks.lean Stat.neyman_pearson_swap -- (phi* - phi)(f1 - k f0) >= 0 as a case split on sign, checked over a grid of (phi, phi', f0, f1) in {0,1}x{0,1}xNat, plus the universal integration step"),
  spec=["N(0,1) vs N(mu_1, 1), mu_1 > 0: f1/f0 is increasing in x, so the MP test is 1{ Xbar > c } -- the one-sided z-test; the SAME test is MP for every mu_1 > 0, which is why it is UMP one-sided",
        "the ROC curve of a diagnostic test is exactly the NP power-vs-size trade-off as k varies",
        "simple-vs-simple is the ONLY case with a clean 'most powerful' test; composite alternatives need MLR (Karlin-Rubin) or unbiasedness restrictions"],
  cxd={"simple_hypotheses": "for a composite two-sided alternative H1: mu != 0 there is NO uniformly most powerful test -- the MP test against mu_1 > 0 (reject for large Xbar) has power BELOW alpha against mu_1 < 0. One must add an unbiasedness or invariance restriction.",
       "known_f0_and_f1": "if f0 or f1 has an unknown nuisance parameter the ratio is not a statistic and the lemma does not directly apply"},
  misuse=["expecting a 'most powerful test' for a composite alternative without a restriction",
          "using the LR test statistic's threshold k from the lemma when the hypotheses are actually composite (then it is the GLR statistic, with a different -- often chi^2 -- reference distribution)"],
  apps=["signal detection theory: the LR test IS the optimal detector (matched filter for Gaussian noise) -- radar, sonar, digital communications (the maximum-likelihood receiver)",
        "the ROC-AUC criterion for classifiers is the NP framework; the Bayes-optimal classifier thresholds the likelihood ratio (= posterior odds)"],
  related={"required_by": ["karlin_rubin_theorem", "likelihood_ratio_test"], "uses": ["likelihood_function", "size_of_test"]},
  sources=["neyman_pearson_1933", "lehmann_romano_tsh"])

N("monotone_likelihood_ratio", "hypothesis", "testing",
  "A family { f(x; theta) } has monotone likelihood ratio in a statistic T(x) if for every theta_1 > theta_0 the ratio f(x; theta_1) / f(x; theta_0) is a nondecreasing function of T(x).",
  parseable="for all theta_1 > theta_0:   f(x; theta_1)/f(x; theta_0)  is nondecreasing in  T(x)",
  symbols={"T(x)": "the statistic in which the ratio is monotone -- the natural sufficient statistic in an exponential family"},
  tcn="An ordering condition on the family. It is what upgrades 'most powerful for a simple alternative' (Neyman-Pearson) to 'UNIFORMLY most powerful for a one-sided composite alternative' (Karlin-Rubin).",
  spec=["every one-parameter exponential family with natural statistic T has MLR in T (the ratio is exp((eta_1 - eta_0) T - (A(eta_1) - A(eta_0))), increasing in T since eta_1 > eta_0)",
        "N(theta, 1) in T = Xbar; Bernoulli(theta) in T = sum X_i; Uniform(0, theta) in T = X_(n) (a non-exponential-family example with MLR)",
        "the noncentral t and noncentral chi^2 families have MLR in their natural statistics"],
  cxd={"MLR_holds": "the Cauchy location family does NOT have MLR -- the likelihood ratio is not monotone, there is no UMP one-sided test, and the one-sided testing problem genuinely has no best solution",
       "two_sided": "MLR gives UMP tests only for ONE-SIDED hypotheses; for H0: theta = theta_0 vs H1: theta != theta_0 even an MLR family has no UMP test"},
  misuse=["assuming a UMP one-sided test exists for a family whose MLR has not been checked",
          "expecting MLR to deliver a UMP two-sided test"],
  related={"required_by": ["karlin_rubin_theorem"], "uses": ["likelihood_function"]},
  sources=["lehmann_romano_tsh", "karlin_rubin_1956"])

N("karlin_rubin_theorem", "theorem", "testing",
  "If the family has monotone likelihood ratio in T, then for testing H0: theta <= theta_0 against H1: theta > theta_0 the test phi(x) = 1{ T(x) > c } (with c set so E_{theta_0}[phi] = alpha) is uniformly most powerful at level alpha: it maximizes beta_phi(theta) for every theta > theta_0 simultaneously.",
  parseable="MLR in T   =>   1{ T > c }  is UMP level-alpha for  H0: theta <= theta_0  vs  H1: theta > theta_0",
  symbols={"UMP": "uniformly most powerful -- the SAME test is most powerful against every alternative at once",
           "the size is attained at theta_0": "MLR makes beta_phi nondecreasing in theta, so sup over theta <= theta_0 is at theta_0"},
  tcn="An optimality theorem for one-sided composite hypotheses. Proof: fix any theta_1 > theta_0; by Neyman-Pearson the MP test of theta_0 vs theta_1 rejects for large f(.; theta_1)/f(.; theta_0), which by MLR is 'large T' -- the same region {T > c} regardless of theta_1. Monotonicity of beta_phi handles the composite null.",
  regime="exact",
  hyps=["monotone_likelihood_ratio"],
  proof=("Neyman-Pearson against an arbitrary theta_1 > theta_0 yields the region {T > c}, which does not depend on theta_1 (MLR); beta_phi nondecreasing (MLR) controls the composite null at theta_0",
         "neyman_pearson_lemma", "cited",
         "the 'NP region is {T > c} independent of theta_1' step follows from MLR monotonicity; the beta nondecreasing lemma is proof-checks.lean Stat.mlr_power_monotone for a two-point family"),
  spec=["N(theta, sigma^2 known): the one-sided z-test 1{ Xbar > mu_0 + z sigma/sqrt(n) } is UMP for H0: mu <= mu_0",
        "Bernoulli: the one-sided binomial test is UMP for H0: p <= p_0",
        "one-sided F-test for a variance ratio; one-sided test for a noncentrality parameter"],
  cxd={"monotone_likelihood_ratio": "Cauchy location, or any family without MLR: no UMP one-sided test exists -- different alternatives are best detected by different regions",
       "one_sided": "for H0: theta = theta_0 vs H1: theta != theta_0 (two-sided) there is no UMP test even under MLR; one restricts to unbiased tests (UMPU) and gets the equal-tailed two-sided test"},
  misuse=["applying it to a two-sided alternative",
          "assuming the one-sided test is 'the' test when a two-sided alternative is scientifically appropriate -- the one-sided test has power below alpha in the wrong direction"],
  related={"uses": ["monotone_likelihood_ratio", "neyman_pearson_lemma"], "generalizes_from": ["neyman_pearson_lemma"]},
  sources=["karlin_rubin_1956", "lehmann_romano_tsh"])

N("likelihood_ratio_test", "definition", "testing",
  "The (generalized) likelihood ratio test for H0: theta in Theta_0 rejects for small values of Lambda(x) = sup_{theta in Theta_0} L(theta; x) / sup_{theta in Theta} L(theta; x); equivalently for large -2 log Lambda.",
  parseable="Lambda(x) = [ sup_{Theta_0} L ] / [ sup_{Theta} L ]  in [0,1];   reject H0 when Lambda <= c   (i.e. -2 log Lambda >= c')",
  symbols={"Lambda in [0,1]": "how much the best null fit is beaten by the best overall fit",
           "-2 log Lambda": "the deviance difference; its null distribution is asymptotically chi^2 (Wilks)"},
  tcn="A general recipe (works for composite hypotheses and nuisance parameters). The exact null distribution of Lambda is problem-specific; the value of the test is that -2 log Lambda -> chi^2_r generically (wilks_theorem).",
  spec=["N(mu, sigma^2), H0: mu = mu_0: -2 log Lambda is a monotone function of the t-statistic^2 -- the LRT IS the two-sided t-test",
        "H0: several regression coefficients are 0: -2 log Lambda ~ the F-test (exactly, under normal errors) or chi^2_q (asymptotically)",
        "multinomial goodness of fit: -2 log Lambda = 2 sum O_j log(O_j/E_j), the G-test, asymptotically chi^2 like Pearson's"],
  cxd={"nested_models": "Lambda requires Theta_0 subset Theta (nested); comparing NON-nested models needs AIC / BIC / Vuong's test, not the LRT",
       "regularity_for_the_chi2_limit": "if H0 is on the boundary of Theta (a variance component = 0) the chi^2_r calibration is wrong (mixture of chi^2's) -- true_parameter_interior again"},
  misuse=["using the chi^2 critical value for a boundary null (variance components, mixture number-of-components)",
          "applying the LRT to non-nested model selection",
          "trusting the chi^2 approximation at small n (the exact or bootstrap null distribution can differ substantially)"],
  apps=["the deviance and 'analysis of deviance' tables in every GLM package",
        "model comparison in phylogenetics, structural equation modeling, item response theory",
        "the profile-likelihood confidence interval is the LRT inverted (confidence_set_test_duality)"],
  related={"uses": ["likelihood_function", "maximum_likelihood_estimator"], "required_by": ["wilks_theorem", "pearson_chi_squared_gof"],
           "special_case_of": []},
  sources=["casella_berger_2e", "lehmann_romano_tsh"])

N("wilks_theorem", "theorem", "testing",
  "Under H0 and the MLE regularity conditions, if Theta_0 is a smooth r-dimensional-lower subset of the d-dimensional Theta, then -2 log Lambda(X) -> chi^2_{d - r} in distribution as n -> inf, where d - r is the number of restrictions.",
  parseable="H0 true + regular   =>   -2 log Lambda(X)  -->^d  chi^2_{ dim(Theta) - dim(Theta_0) }",
  symbols={"d - r = number of free parameters fixed by H0": "the chi^2 degrees of freedom",
           "Lambda": "the GLR statistic"},
  tcn="An asymptotic null-distribution result -- it makes the LRT usable without deriving an exact null law. Proof: Taylor-expand ell around theta_hat and around theta_hat_0 (the constrained MLE); both expansions are quadratic forms in asymptotically-normal score vectors with covariance I; the difference is a chi^2_{d-r} by the projection/idempotency algebra.",
  regime="asymptotic",
  hyps=["true_parameter_interior", "fisher_information_positive_definite", "log_likelihood_smooth"],
  proof=("quadratic expansion of the log-likelihood at the two MLEs; -2 log Lambda = (score)^T (projection) (score) + o_p(1), a chi^2_{d-r} by Cochran-type algebra on the asymptotically N(0, I) score",
         "mle_asymptotic_normality", "cited",
         "CITED -- Wilks 1938; van der Vaart Thm 16.7. The 'difference of two quadratic forms is chi^2_{d-r}' idempotency step reuses proof-checks.lean Stat.cochran_idempotent."),
  spec=["one restriction (d - r = 1): -2 log Lambda -> chi^2_1, and sqrt(-2 log Lambda) is asymptotically |N(0,1)| -- matches the Wald and score tests",
        "testing q of p regression coefficients zero: -2 log Lambda -> chi^2_q (and q F_{q, n-p} -> chi^2_q, so the exact F-test and Wilks agree in the limit)",
        "the LRT confidence region { theta_0 : -2 log Lambda(theta_0) <= chi^2_{d, 1-alpha} } -- the profile-likelihood region"],
  cxd={"true_parameter_interior": "H0 on the boundary (sigma^2_component = 0, testing k vs k+1 mixture components): -2 log Lambda is NOT chi^2_r -- it is a mixture (e.g. 0.5 chi^2_0 + 0.5 chi^2_1) or has an even more complex limit. Using chi^2_r is conservative here.",
       "log_likelihood_smooth": "non-regular models (uniform endpoint): -2 log Lambda has a non-chi^2 limit (often exponential-related)",
       "nested_and_smooth_Theta_0": "if Theta_0 is not a smooth submanifold (e.g. a single point in a curved family, or a non-identified restriction) the df count d - r can be wrong"},
  misuse=["using chi^2_r critical values for variance-component or number-of-components tests (boundary null)",
          "trusting the chi^2 approximation at small n -- Bartlett's correction or a bootstrap null distribution is often needed",
          "counting restrictions wrong when Theta_0 is defined by nonlinear constraints"],
  apps=["the reference distribution for essentially every 'likelihood ratio test' / 'analysis of deviance' reported in applied statistics",
        "sequential testing of the number of factors / components / change-points"],
  related={"uses": ["likelihood_ratio_test", "mle_asymptotic_normality", "chi_squared_distribution"],
           "required_by": ["three_tests_asymptotically_equivalent", "pearson_chi_squared_gof"]},
  sources=["wilks_1938", "van_der_vaart_asymptotic", "self_liang_1987"])

N("wald_test", "definition", "testing",
  "The Wald test of H0: theta = theta_0 rejects when W = (theta_hat - theta_0)^T [n I(theta_hat)] (theta_hat - theta_0) exceeds chi^2_{d, 1-alpha} (scalar case: (theta_hat - theta_0)^2 n I(theta_hat) > chi^2_{1,1-alpha}). It uses only the UNRESTRICTED fit.",
  parseable="W = (theta_hat - theta_0)^T [ n I(theta_hat) ] (theta_hat - theta_0);   reject if W > chi^2_{d, 1-alpha}",
  symbols={"theta_hat": "the unrestricted MLE", "n I(theta_hat)": "estimated sample information (or observed information)",
           "W -> chi^2_d under H0": "by mle_asymptotic_normality + continuous mapping"},
  tcn="An asymptotic test; the quadratic form of a standardized N(0, I^{-1}) vector is chi^2_d. Needs only the alternative-model fit -- convenient, but NOT invariant to reparametrization (W changes if you test log theta vs theta), its worst practical flaw.",
  regime="asymptotic",
  hyps=["true_parameter_interior", "fisher_information_positive_definite"],
  proof=("mle_asymptotic_normality: sqrt(n)(theta_hat - theta_0) -> N(0, I^{-1}) under H0; the quadratic form with the inverse covariance -> chi^2_d (continuous mapping)",
         "mle_asymptotic_normality", "cited", None),
  spec=["scalar: W = (theta_hat - theta_0)^2 / se^2 = (z-statistic)^2 -- the squared 'estimate over standard error'",
        "the z-values printed next to GLM coefficients ARE Wald tests of H0: beta_j = 0",
        "for a linear model with normal errors the Wald test of several coefficients is exactly q F_{q, n-p} rescaled"],
  cxd={"reparametrization": "testing H0: theta = 1 vs H0: log theta = 0 gives DIFFERENT Wald statistics and p-values though the hypotheses are identical -- the Wald test is not invariant. The LRT and score test are.",
       "true_parameter_interior": "the 'Hauck-Donner effect': for a logistic coefficient far from 0 with a large SE, W can DECREASE as the effect grows, so the Wald test loses power exactly when the effect is large. Use the LRT.",
       "fisher_information_positive_definite": "near-singular information (collinearity) makes W numerically unstable"},
  misuse=["preferring the Wald test for its convenience when the log-likelihood is asymmetric (small n, near-boundary) -- the LRT is more reliable",
          "reporting Wald p-values for a logistic model with near-separation (Hauck-Donner)"],
  related={"uses": ["mle_asymptotic_normality", "fisher_information", "chi_squared_distribution"],
           "required_by": ["three_tests_asymptotically_equivalent"]},
  sources=["wald_1943", "casella_berger_2e", "hauck_donner_1977"])

N("score_test", "definition", "testing",
  "The score (Rao / Lagrange-multiplier) test of H0: theta = theta_0 rejects when U(theta_0)^T [n I(theta_0)]^{-1} U(theta_0) exceeds chi^2_{d, 1-alpha}. It uses ONLY the null fit -- no need to estimate the alternative model.",
  parseable="S = U(theta_0)^T [ n I(theta_0) ]^{-1} U(theta_0);   reject if S > chi^2_{d, 1-alpha}",
  symbols={"U(theta_0)": "the score evaluated at the hypothesized value -- large in magnitude => theta_0 is a poor fit",
           "everything evaluated at theta_0": "the practical advantage: only fit the restricted model"},
  tcn="An asymptotic test. Under H0, (1/sqrt n) U(theta_0) -> N(0, I(theta_0)) (score identity + information equality), so the standardized quadratic form -> chi^2_d. Invariant to reparametrization. Ideal when the alternative model is hard to fit (many nuisance parameters) or when scanning many candidate additions.",
  regime="asymptotic",
  hyps=["fisher_information_positive_definite"],
  proof=("score identity: E_{theta_0}[U(theta_0)] = 0; CLT: (1/sqrt n) U(theta_0) -> N(0, I(theta_0)); standardize and apply continuous mapping to get chi^2_d",
         "information_equality", "cited", None),
  spec=["Pearson's chi-squared goodness-of-fit statistic IS the score test for the multinomial (pearson_chi_squared_gof)",
        "the Breusch-Pagan test for heteroskedasticity and the Breusch-Godfrey test for autocorrelation are score (LM) tests",
        "testing whether to add a variable to a regression: the score test needs only the model WITHOUT it -- efficient for variable screening"],
  cxd={"fisher_information_positive_definite": "singular I(theta_0) (a redundant restriction) makes the inverse undefined",
       "H0_regular": "if theta_0 is on the boundary the score does not have mean 0 in the two-sided sense and the chi^2 calibration fails"},
  misuse=["using the observed information at theta_0 vs the expected information inconsistently -- they differ and the choice affects small-sample behaviour",
          "treating the score test as exact -- it is asymptotic like Wald and Wilks"],
  apps=["variable-selection screening in high-dimensional regression (score tests for each candidate, no refit)",
        "the score test underlies the 'modification indices' in structural equation modeling"],
  related={"uses": ["score_function", "information_equality", "chi_squared_distribution"],
           "required_by": ["three_tests_asymptotically_equivalent", "pearson_chi_squared_gof"]},
  sources=["rao_1948", "casella_berger_2e"])

N("three_tests_asymptotically_equivalent", "theorem", "testing",
  "Under H0 and local alternatives theta_n = theta_0 + h/sqrt(n), the Wald, score, and likelihood-ratio statistics differ by o_p(1) and share the same limiting (noncentral) chi^2_{d-r} distribution; asymptotically the three tests have identical size and power.",
  parseable="under H0 / local alternatives:   W - S = o_p(1),   W - (-2 log Lambda) = o_p(1)   =>   same chi^2_{d-r} limit",
  symbols={"o_p(1)": "converges to 0 in probability", "local alternatives h/sqrt(n)": "the regime where power is non-degenerate (between alpha and 1)"},
  tcn="An asymptotic-equivalence statement. All three are, to first order, the same quadratic form in the asymptotically-normal score; they differ only in whether the information is evaluated at theta_hat (Wald), theta_0 (score), or effectively averaged (LRT), and in second-order terms.",
  regime="asymptotic",
  hyps=["true_parameter_interior", "fisher_information_positive_definite", "log_likelihood_smooth"],
  proof=("Taylor-expand each statistic around theta_0; the leading quadratic term is common; the differences are O_p(1/sqrt n) under H0 and local alternatives",
         "wilks_theorem", "cited",
         "CITED -- Engle 1984 (Handbook of Econometrics Ch. 13); van der Vaart Ch. 16. The shared quadratic form is the content."),
  spec=["scalar linear-normal case: all three reduce EXACTLY (not just asymptotically) to the t^2 / F statistic",
        "for a proportion: Wald uses p_hat(1-p_hat), score uses p_0(1-p_0) -- the score (Wilson) test/interval has far better small-sample coverage though they agree in the limit",
        "ordering in finite samples is problem-dependent, but often -2 log Lambda is between W and S"],
  cxd={"regularity_all_three": "at a boundary or in a non-regular model the three can have DIFFERENT (non-chi^2) limits and are no longer equivalent",
       "far_from_local": "against a FIXED (non-local) alternative all three have power -> 1 but at different rates; 'equivalent' is a local statement"},
  misuse=["citing the equivalence to justify using the most convenient test (Wald) at a small n where they visibly disagree -- pick the one with the best finite-sample properties (usually score or LRT)",
          "assuming equal power against a fixed large alternative"],
  related={"uses": ["wald_test", "score_test", "wilks_theorem"]},
  sources=["engle_1984", "van_der_vaart_asymptotic"])

N("p_value", "definition", "testing",
  "The p-value is the smallest level alpha at which the observed data would lead to rejection; for a test rejecting for large T, p(x) = sup_{theta in Theta_0} P_theta( T(X) >= T(x) ). It is a statistic, computed after seeing the data.",
  parseable="p(x) = sup_{theta in Theta_0} P_theta( T(X) >= T(x_obs) )",
  symbols={"T(x_obs)": "the observed test statistic", "P_theta(T >= T(x_obs))": "the null tail probability at least as extreme as observed"},
  tcn="A [0,1]-valued statistic (a random variable before the data are seen). Under a simple continuous null it is Uniform(0,1) (p_value_uniform_under_null). Reject at level alpha iff p <= alpha. It is NOT P(H0 true | data) and NOT the probability the result is a fluke.",
  regime="exact",
  spec=["one-sample t-test: p = 2 P(t_{n-1} >= |t_obs|)",
        "a p-value of 0.03 means: IF H0 held, data this extreme or more would occur 3% of the time",
        "the p-value curve over candidate null values traces out (one minus) the confidence-interval coverage -- p > alpha exactly for theta_0 in the 1 - alpha CI"],
  cxd={"simple_null_or_sup_taken": "with a composite null and a non-pivotal statistic the sup is intractable; one uses a plug-in or a similar test, and the p-value is only approximately calibrated",
       "T_continuous": "for discrete data the p-value is not Uniform under H0 -- it is stochastically larger (the test is conservative)"},
  misuse=["reporting p as the probability H0 is true, or as 1 minus the probability the finding replicates",
          "treating p = 0.049 and p = 0.051 as categorically different",
          "'p > 0.05 therefore no effect' -- ignores power and the confidence interval",
          "p-hacking: trying analyses until p < 0.05 (inflates the true Type I rate far above 0.05)"],
  apps=["the near-universal (and heavily criticized) summary of evidence in the experimental literature; the ASA 2016 statement and 'moving to a world beyond p < 0.05' are the field's response",
        "genome-wide association studies use p < 5e-8 (Bonferroni for ~1e6 independent tests)"],
  related={"uses": ["size_of_test", "test_function"], "required_by": ["p_value_uniform_under_null", "benjamini_hochberg_fdr"],
           "commonly_confused_with": ["posterior_mean_rule"]},
  sources=["casella_berger_2e", "wasserstein_lazar_2016"])

N("p_value_uniform_under_null", "proposition", "testing",
  "If the test statistic T has a continuous distribution and the null H0 is simple, then the p-value p(X) is exactly Uniform(0,1) under H0; hence P_{H0}(p(X) <= alpha) = alpha and rejecting when p <= alpha has size exactly alpha.",
  parseable="H0 simple, T continuous   =>   p(X) ~ Uniform(0,1)  under H0",
  symbols={"p(X) = 1 - F_0(T(X))": "for an upper-tail test, F_0 the null CDF of T -- a probability integral transform"},
  tcn="An exact distributional fact, a direct corollary of the probability integral transform (F_0(T) ~ Uniform when T ~ F_0 continuous). It is what makes the p-value a calibrated evidence scale and lets p-values be combined (Fisher's method, etc.).",
  regime="exact",
  hyps=[],
  proof=("probability integral transform: if T ~ F_0 continuous then F_0(T) ~ Uniform(0,1), so p(X) = 1 - F_0(T(X)) ~ Uniform(0,1)",
         "prob_cdf", "core",
         "the PIT step F(T) ~ Uniform is cited to math-probability:probability_integral_transform; the corollary is one line"),
  spec=["a histogram of p-values across many true nulls should look flat -- a spike near 0 signals real effects, a spike near 1 signals a misspecified (conservative) test or dependence",
        "under the ALTERNATIVE, the p-value distribution is stochastically smaller than Uniform (concentrated near 0), and more so with higher power",
        "discrete T: p(X) is stochastically LARGER than Uniform -- P(p <= alpha) < alpha, the test is conservative"],
  cxd={"T_continuous": "binomial / Poisson / permutation tests with few distinct values: the p-value takes finitely many values and P(p <= alpha) jumps below alpha -- 'mid-p' or randomized p-values restore uniformity",
       "H0_simple": "with a composite null the p-value defined via the sup is Uniform at the least-favorable null point and stochastically larger elsewhere"},
  misuse=["assuming a uniform p-value histogram for discrete tests",
          "combining dependent p-values with Fisher's method as if independent"],
  related={"uses": ["p_value", "prob_cdf"]},
  sources=["casella_berger_2e", "murdoch_tsai_adcock_2008"])

N("pearson_chi_squared_gof", "theorem", "testing",
  "For n observations classified into k cells with null cell probabilities p_j(theta) (d parameters estimated by an efficient method), the Pearson statistic X^2 = sum_{j=1}^k (O_j - E_j)^2 / E_j (O_j observed, E_j = n p_j(theta_hat)) converges under H0 to chi^2_{k - 1 - d}.",
  parseable="X^2 = sum_j (O_j - E_j)^2 / E_j   -->^d   chi^2_{ k - 1 - d }   under H0",
  symbols={"O_j": "observed count in cell j", "E_j = n p_j(theta_hat)": "expected count under the fitted null",
           "k - 1 - d": "cells, minus 1 (counts sum to n), minus d estimated parameters"},
  tcn="An asymptotic null-distribution result. X^2 is (asymptotically) the score statistic for the multinomial model, hence chi^2; it is also asymptotically equivalent to the LR statistic G^2 = 2 sum O_j log(O_j/E_j) (three_tests_asymptotically_equivalent).",
  regime="asymptotic",
  hyps=["fisher_information_positive_definite"],
  proof=("multivariate CLT for the cell counts -> N(0, Sigma); X^2 is the corresponding quadratic form; a rank argument gives df k - 1, reduced by d for efficiently estimated parameters (Fisher's df correction)",
         "score_test", "cited",
         "CITED -- Pearson 1900; Fisher 1924 (df correction); Cramer 1946. X^2 as the multinomial score statistic is the modern view."),
  spec=["testing a fully specified distribution (d = 0): df = k - 1",
        "test of independence in an r x c table: d = (r-1) + (c-1) estimated margins, df = (r-1)(c-1)",
        "rule of thumb: valid when all E_j >= 5 (else exact / Monte Carlo tests)"],
  cxd={"parameters_estimated_efficiently_AND_from_grouped_data": "if theta is estimated from the RAW (ungrouped) data rather than the cell counts, the limiting distribution is BETWEEN chi^2_{k-1-d} and chi^2_{k-1} (Chernoff-Lehmann) -- using chi^2_{k-1-d} then over-rejects",
       "large_expected_counts": "sparse tables (many E_j < 5): the chi^2 approximation fails; the statistic is not chi^2 and can be wildly miscalibrated"},
  misuse=["using chi^2_{k-1-d} when parameters were fit to ungrouped data (Chernoff-Lehmann)",
          "applying it to sparse contingency tables without an exact test",
          "reading a non-significant GOF test as 'the model fits' (low power against many alternatives)"],
  apps=["the chi^2 test of independence -- the most common categorical-data analysis in the social sciences",
        "goodness-of-fit checks in genetics (Hardy-Weinberg), physics (histogram fits), and A/B testing (does the traffic split match design?)"],
  related={"uses": ["likelihood_ratio_test", "chi_squared_distribution", "prob_clt"], "special_case_of": ["wilks_theorem"]},
  sources=["pearson_1900", "fisher_1924", "cramer_1946"])

N("multiple_testing_fwer", "definition", "testing",
  "When m hypotheses H_{0,1}, ..., H_{0,m} are tested together, the family-wise error rate is FWER = P( at least one true null is rejected ). Controlling FWER <= alpha bounds the chance of ANY false positive across the family.",
  parseable="FWER = P( reject at least one H_{0,i} that is true )   <=  alpha",
  symbols={"m": "the number of tests in the family", "the family": "the set of hypotheses over which error is controlled -- a modelling choice"},
  tcn="A joint (across the family) Type I error criterion. If each of m independent true nulls is tested at level alpha, P(at least one rejection) = 1 - (1 - alpha)^m approx m alpha -- so per-test alpha must shrink.",
  spec=["m = 20 independent tests at 0.05 each: FWER approx 1 - 0.95^20 = 0.64 -- a coin flip that SOMETHING is 'significant'",
        "FWER control is appropriate when even one false claim is costly (a drug's primary + key secondary endpoints)",
        "for large-scale screening (genomics) FWER is too strict and FDR is used instead"],
  cxd={"the_family_is_well_defined": "if the analyst does not fix the family in advance, the 'number of tests' is ambiguous and any correction is gameable -- the multiplicity problem is really a pre-registration problem"},
  misuse=["defining the family narrowly after the fact to avoid a harsh correction",
          "applying FWER control to thousands of exploratory tests, killing all power",
          "ignoring multiplicity entirely across a paper's dozens of tests"],
  related={"uses": ["size_of_test", "null_hypothesis"], "required_by": ["bonferroni_correction", "benjamini_hochberg_fdr"]},
  sources=["lehmann_romano_tsh", "hochberg_tamhane_multiple_comparison"])

N("bonferroni_correction", "proposition", "testing",
  "Testing each of m hypotheses at level alpha/m controls the family-wise error rate at alpha, for ANY dependence structure among the tests.",
  parseable="test each H_{0,i} at level alpha/m   =>   FWER <= alpha   (no independence assumption)",
  symbols={"alpha/m": "the per-comparison level", "equivalently": "reject H_{0,i} if its p-value p_i <= alpha/m; or adjust p_i -> min(1, m p_i)"},
  tcn="A finite-sample FWER bound. Proof: Boole's inequality (the union bound) -- FWER = P(union of false rejections) <= sum P(false rejection_i) <= m_0 (alpha/m) <= alpha, where m_0 <= m is the number of true nulls.",
  regime="exact",
  hyps=[],
  proof=("Boole / union bound over the true nulls: P(any true null rejected) <= sum_{i true null} P(reject H_{0,i}) <= m_0 alpha/m <= alpha",
         "prob_markov_ineq", "core",
         "the union bound P(union A_i) <= sum P(A_i) is cited to math-probability:boole_inequality; the arithmetic m_0 alpha/m <= alpha is proof-checks.lean Stat.bonferroni_bound"),
  spec=["Holm's step-down procedure uniformly improves on Bonferroni at no cost (also FWER, any dependence) -- always prefer it",
        "m = 2 (co-primary endpoints): test each at 0.025",
        "for POSITIVELY dependent tests Bonferroni is conservative; Sidak (1 - (1-alpha)^{1/m}) is slightly tighter under independence"],
  cxd={"none_all_hypotheses_essential": "the bound holds unconditionally; its weakness is conservatism (low power) when m is large or tests are positively dependent, not invalidity"},
  misuse=["using raw Bonferroni when Holm is strictly better",
          "applying it to 10^6 genomic tests -- valid but essentially no power; use FDR",
          "correcting for tests you happened to run but that were not part of the pre-specified family (over-correction)"],
  apps=["the standard adjustment for a small number of pre-specified secondary endpoints in clinical trials",
        "'genome-wide significance' p < 5e-8 is Bonferroni for ~1e6 independent common variants"],
  related={"uses": ["multiple_testing_fwer", "prob_markov_ineq"], "improved_by": []},
  sources=["bonferroni_1936", "holm_1979", "lehmann_romano_tsh"])

N("benjamini_hochberg_fdr", "proposition", "testing",
  "The false discovery rate is FDR = E[ (false rejections) / max(1, total rejections) ]. The Benjamini-Hochberg step-up procedure -- order p_(1) <= ... <= p_(m), find the largest k with p_(k) <= (k/m) alpha, reject H_(1), ..., H_(k) -- controls FDR <= (m_0/m) alpha <= alpha under independence (and under positive regression dependence, PRDS).",
  parseable="reject the k smallest p-values, where k = max{ j : p_(j) <= (j/m) alpha };   then FDR <= (m_0/m) alpha",
  symbols={"FDR": "expected fraction of rejections that are false (0 if no rejections)",
           "(k/m) alpha": "the rising BH threshold on the ordered p-values"},
  tcn="A weaker, more powerful error criterion than FWER: it tolerates a controlled FRACTION of false positives among the discoveries, which is the right notion for large-scale screening. FDR = FWER when all nulls are true; otherwise FDR <= FWER, so FDR procedures reject more.",
  regime="distribution_free",
  hyps=[],
  proof=("Benjamini-Hochberg 1995 (independence); Benjamini-Yekutieli 2001 (PRDS, and a log-factor-corrected version for arbitrary dependence)",
         "p_value_uniform_under_null", "cited",
         "CITED -- Benjamini-Hochberg 1995; Storey 2002 (the martingale proof). The step-up threshold arithmetic is checked on a fixed p-value vector in instance-checks.bc."),
  spec=["m = 100, alpha = 0.05, if 10 p-values are below 0.005: BH rejects them -- expected ~0.5 false among the 10",
        "the adaptive (Storey) version estimates m_0 and is less conservative",
        "q-values (Storey) are the FDR analogue of p-values -- the minimum FDR at which a given test is called significant"],
  cxd={"independence_or_PRDS": "under arbitrary (e.g. negative) dependence the plain BH procedure can exceed alpha; the Benjamini-Yekutieli correction divides alpha by sum_{i=1}^m 1/i (~ log m), restoring control at a power cost",
       "many_true_nulls": "if m_0 = m (all null) FDR control coincides with weak FWER control -- BH does not waste power there"},
  misuse=["reporting BH-adjusted p-values but interpreting an individual 'discovery' as if FWER-controlled (it is not -- a specific finding still has a real chance of being false)",
          "using plain BH under strong negative dependence"],
  apps=["the default multiplicity control in genomics (differential expression, GWAS secondary analyses), neuroimaging (fMRI voxel maps), and proteomics -- BH 1995 is one of the most-cited statistics papers ever",
        "large-scale A/B testing platforms use FDR control across simultaneously-running experiments"],
  related={"uses": ["multiple_testing_fwer", "p_value"], "generalizes_from": []},
  sources=["benjamini_hochberg_1995", "benjamini_yekutieli_2001", "storey_2002"])

N("one_sample_t_test", "proposition", "testing",
  "For X_1..X_n iid N(mu, sigma^2), the test that rejects H0: mu = mu_0 when |sqrt(n)(Xbar - mu_0)/S| > t_{n-1, 1-alpha/2} has size exactly alpha; it is the two-sided UMP-unbiased test and the LRT for this problem.",
  parseable="reject H0: mu = mu_0  iff  | sqrt(n)(Xbar - mu_0)/S | > t_{n-1, 1-alpha/2};   size = alpha exactly",
  symbols={"t = sqrt(n)(Xbar - mu_0)/S": "the t-statistic, ~ t_{n-1} under H0 (t_statistic_distribution)",
           "the one-sided version": "rejects when t > t_{n-1, 1-alpha}, UMP for H0: mu <= mu_0"},
  tcn="An exact-level test. The statistic is pivotal under the whole composite null {mu = mu_0, sigma^2 > 0} because its null law t_{n-1} does not involve sigma^2 -- so the size is alpha for every sigma^2.",
  regime="exact",
  hyps=[],
  proof=("t_statistic_distribution: under H0 the statistic is exactly t_{n-1}, free of the nuisance sigma^2; so P_{H0}(|t| > t_{n-1,1-alpha/2}) = alpha for every sigma^2",
         "t_statistic_distribution", "core", None),
  spec=["paired design: apply to the within-pair differences d_i = X_i - Y_i, testing H0: mean difference = 0",
        "one-sided: H0: mu <= mu_0 vs H1: mu > mu_0, reject for large t -- UMP by Karlin-Rubin (MLR in Xbar)",
        "the dual t confidence interval is Xbar +- t S/sqrt(n) (normal_mean_ci_unknown_variance)"],
  cxd={"normality": "small skewed samples: the actual size deviates from alpha (up to ~0.08-0.10 for strongly skewed n ~ 10); large n rescues the LEVEL via the CLT (t -> N(0,1) regardless of parent) but not necessarily the power comparison",
       "iid": "correlated data (repeated measures analysed as independent): the true SE of Xbar is underestimated, t is inflated, the test over-rejects badly"},
  misuse=["using it on clearly non-normal small samples instead of a signed-rank or bootstrap test",
          "running paired data as two independent samples (or vice versa)",
          "reading a non-significant result from an underpowered study as evidence of no effect"],
  apps=["the workhorse significance test of experimental psychology, biology, and medicine",
        "quality control: is a batch's mean within spec?"],
  related={"uses": ["t_statistic_distribution", "size_of_test"], "special_case_of": ["likelihood_ratio_test"],
           "dual_of": ["normal_mean_ci_unknown_variance"]},
  sources=["student_1908", "lehmann_romano_tsh"])

N("two_sample_t_test", "proposition", "testing",
  "For independent normal samples X_1..X_n ~ N(mu_X, sigma^2) and Y_1..Y_m ~ N(mu_Y, sigma^2) with EQUAL variances, the pooled statistic (Xbar - Ybar - delta_0) / (S_p sqrt(1/n + 1/m)) ~ t_{n+m-2} under H0: mu_X - mu_Y = delta_0, giving an exact-level test. When variances are unequal, Welch's statistic with Satterthwaite degrees of freedom is used (approximate).",
  parseable="equal var:  (Xbar - Ybar - delta_0) / ( S_p sqrt(1/n + 1/m) )  ~  t_{n+m-2}   under H0",
  symbols={"S_p^2 = [(n-1)S_X^2 + (m-1)S_Y^2] / (n+m-2)": "the pooled variance estimate",
           "Welch df": "nu = (S_X^2/n + S_Y^2/m)^2 / [ (S_X^2/n)^2/(n-1) + (S_Y^2/m)^2/(m-1) ]"},
  tcn="Exact under normality + equal variances (the pooled statistic is pivotal, ~ t_{n+m-2}). Welch's version is only approximately t-distributed (the Behrens-Fisher problem has no exact solution with a pivotal statistic).",
  regime="exact",
  hyps=[],
  proof=("Xbar - Ybar ~ N(mu_X - mu_Y, sigma^2(1/n + 1/m)); (n+m-2)S_p^2/sigma^2 ~ chi^2_{n+m-2} independent of it (sum of two independent scaled sample variances); assemble the t definition",
         "t_statistic_distribution", "core", None),
  spec=["n = m and equal variances: pooled and Welch give nearly identical results",
        "very unequal variances or sample sizes: pooled test can be badly miscalibrated -- Welch is the safer default (and is now the default in R's t.test)",
        "the ANOVA F-test with k = 2 groups equals the pooled two-sample t^2"],
  cxd={"equal_variances_for_the_pooled_version": "n=5 with sigma_X = 1 and m=50 with sigma_Y = 4: the pooled t-test's true size can be 0.15+ at nominal 0.05 -- pooling a large-sample large-variance group drags S_p^2 wrongly. Use Welch.",
       "normality": "same small-sample skew caveat as the one-sample test",
       "independence_between_samples": "matched/paired data must use the one-sample test on differences -- treating pairs as independent throws away the pairing and usually loses power"},
  misuse=["defaulting to the equal-variance pooled test without checking (or just using Welch, which costs little when variances ARE equal)",
          "analysing paired data as two independent samples"],
  apps=["comparing a treatment and control group mean -- the single most common hypothesis test in the applied sciences and in A/B testing"],
  related={"uses": ["t_statistic_distribution", "prob_normal_affine_closure"], "special_case_of": ["overall_f_test"]},
  sources=["welch_1947", "lehmann_romano_tsh", "casella_berger_2e"])

N("f_test_equality_of_variances", "proposition", "testing",
  "For independent normal samples of sizes n and m, S_X^2 / S_Y^2 ~ F_{n-1, m-1} under H0: sigma_X^2 = sigma_Y^2; reject when the ratio is outside [F_{n-1,m-1,alpha/2}, F_{n-1,m-1,1-alpha/2}]. Exact under normality, but highly non-robust to non-normality.",
  parseable="S_X^2 / S_Y^2  ~  F_{n-1, m-1}   under H0: sigma_X^2 = sigma_Y^2",
  symbols={"the ratio of sample variances": "each S^2 scaled to a chi^2, the ratio is an F"},
  tcn="Exact under normality (ratio of independent scaled chi-squares). Its Achilles heel: the F-test for variances is extremely sensitive to kurtosis -- far more than the t-test for means. Levene's and Brown-Forsythe tests are robust alternatives.",
  regime="exact",
  hyps=[],
  proof=("(n-1)S_X^2/sigma_X^2 ~ chi^2_{n-1} _||_ (m-1)S_Y^2/sigma_Y^2 ~ chi^2_{m-1}; under H0 the sigma^2's cancel in the ratio, giving F_{n-1,m-1} by definition",
         "f_distribution", "core", None),
  spec=["used as a (poor) preliminary check before a pooled two-sample t-test -- this two-stage procedure is now discouraged; just use Welch",
        "one-sided: test whether a new process REDUCES variance",
        "k-sample generalization: Bartlett's test (also non-robust) or Levene's test (robust)"],
  cxd={"normality": "with heavy-tailed data (kurtosis > 3) the F-test for variances has true size FAR above nominal -- e.g. 0.20 at nominal 0.05 for t_5 data. This is the textbook example of a procedure that must not be used without near-exact normality.",
       "independence": "paired or correlated samples invalidate the chi^2 factorization"},
  misuse=["using it to 'justify' pooling in a two-sample t-test (the two-stage procedure has poor overall properties)",
          "applying it to non-normal data -- prefer Levene / Brown-Forsythe"],
  related={"uses": ["f_distribution", "scaled_sample_variance_chi_squared"], "robust_alternative": []},
  sources=["casella_berger_2e", "box_1953"])
